commands:
# Run as admin

 # 1) Uninstall Mozilla Maintenance Service if available
 $uninstaller = 'C:\Program Files (x86)\Mozilla Maintenance Service\Uninstall.exe'
 if (Test-Path $uninstaller) {
  Start-Process -FilePath $uninstaller -ArgumentList '/S' -WindowStyle Hidden -ErrorAction SilentlyContinue
 }

 # 2) Remove unwanted Firefox executables
 $firefoxPath = 'C:\Program Files\Mozilla Firefox'
 $filesToDelete = @(
  'crashreporter.exe',
  'crashreporter.ini',
  'maintenanceservice.exe',
  'maintenanceservice_installer.exe',
  'minidump-analyzer.exe',
  'pingsender.exe'
  # 'updater.exe' # intentionally left disabled
 )
 foreach ($file in $filesToDelete) {
  $f = Join-Path $firefoxPath $file
  if (Test-Path $f) { Remove-Item $f -Force -ErrorAction SilentlyContinue }
 }

 # 3) Delete crash/maintenance logs and temporary files
 if (Test-Path $firefoxPath) {
  Get-ChildItem -Path $firefoxPath -Filter 'crash*.*' -ErrorAction SilentlyContinue | Remove-Item -Force -ErrorAction SilentlyContinue
  Get-ChildItem -Path $firefoxPath -Filter 'maintenance*.*' -ErrorAction SilentlyContinue | Remove-Item -Force -ErrorAction SilentlyContinue
  if (Test-Path (Join-Path $firefoxPath 'install.log')) {
  Remove-Item (Join-Path $firefoxPath 'install.log') -Force -ErrorAction SilentlyContinue
  }
  Get-ChildItem -Path $firefoxPath -Filter 'minidump*.*' -ErrorAction SilentlyContinue | Remove-Item -Force -ErrorAction SilentlyContinue
 }
